var game=UnityEngine.Object.FindFirstObjectByType<Corrigible.Ayna.Game.AynaGameController>();
var before=game.ExportSave(); var world=game.Match.Simulation.Board(Corrigible.Ayna.Core.Side.Player);
var command=Corrigible.Ayna.Core.BoardSimulation.CreateBelief(world).LegalCommands(Corrigible.Ayna.Core.Side.Player).First(c=>c.Action==Corrigible.Ayna.Core.BoardAction.Move);
var view=UnityEngine.Object.FindFirstObjectByType<Corrigible.Ayna.Game.AynaDebugView>();var serial=new UnityEditor.SerializedObject(view);
var unit=(TMPro.TMP_Dropdown)serial.FindProperty("boardUnit").objectReferenceValue;
var ids=game.Screens.A6.Units.Where(u=>u.Controller==Corrigible.Ayna.Core.Side.Player).Select(u=>u.Id).ToArray();unit.value=System.Array.IndexOf(ids,command.UnitId);
var action=(TMPro.TMP_Dropdown)serial.FindProperty("boardAction").objectReferenceValue;action.value=(int)command.Action;
var cell=(UnityEngine.UI.Button)serial.FindProperty("cells").GetArrayElementAtIndex(command.To).objectReferenceValue;cell.onClick.Invoke();
bool previewPure=game.ExportSave()==before;
var apply=(UnityEngine.UI.Button)serial.FindProperty("applyBoardButton").objectReferenceValue;apply.onClick.Invoke();
bool moved=game.Match.Simulation.Board(Corrigible.Ayna.Core.Side.Player).Units.First(u=>u.Id==command.UnitId).Cell==command.To;
var undo=(UnityEngine.UI.Button)serial.FindProperty("undoButton").objectReferenceValue;undo.onClick.Invoke();
bool restored=game.Match.Simulation.Board(Corrigible.Ayna.Core.Side.Player).Units.First(u=>u.Id==command.UnitId).Cell==world.Units.First(u=>u.Id==command.UnitId).Cell;
game.LoadGame();
return new{PreviewPure=previewPure,Moved=moved,UndoRestored=restored,SaveRestored=game.ExportSave()==System.IO.File.ReadAllText("Temp/AynaF4BoardSave.json")};
